Problem:
An internet supplier needs to deliver routers to their customers when they first sign up. They can either transport using their internal drivers or outsource to external drivers. Internal drivers spend more time to help the customers set up and can deliver 20 routers every day whereas the external drivers can deliver 35 routers every day. External drivers use hybrid cars and produce 5 units of pollution while the internal drivers use gasoline cars and produce 12 units of pollution. The internet supplier needs to deliver at least 500 routers every day and internal drivers must make up at least 20% of all drivers due to their customer service. There must also be at least 5 external drivers. How many of each type of driver should the internet supplier plan to contract to minimize the total amount of pollution?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "internal drivers",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "external drivers",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "internal drivers",
     "coef": 12.0
    },
    {
     "var": "external drivers",
     "coef": 5.0
    }
   ]
  },
  "constraints": [
   {
    "name": "daily deliveries",
    "terms": [
     {
      "var": "internal drivers",
      "coef": 20.0
     },
     {
      "var": "external drivers",
      "coef": 35.0
     }
    ],
    "sense": ">=",
    "rhs": 500.0
   },
   {
    "name": "internal share of drivers",
    "terms": [
     {
      "var": "internal drivers",
      "coef": 0.8
     },
     {
      "var": "external drivers",
      "coef": -0.2
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "minimum external drivers",
    "terms": [
     {
      "var": "external drivers",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 5.0
   }
  ]
 },
 "facts": {
  "objective": 108.0,
  "values": {
   "internal drivers": 4.0,
   "external drivers": 12.0
  },
  "binding": [
   "daily deliveries"
  ],
  "slack": {
   "daily deliveries": 0.0,
   "internal share of drivers": 0.8,
   "minimum external drivers": 7.0
  },
  "shadow_prices": null
 }
}
